# 57b_fig4_fig5_v137.R  Figs. 4 and 5 of manuscript v137: script 55 with presentation changes only (Aaron, November 18, 2026). Fig. 4: origin titles
# once (top row), wider gap between the origin panels so end ticks do not collide, two-line axis titles so panel tags clear them. Fig. 5: the yellow
# wash is replaced by a dashed vertical line where the benchmark record ends (year 33 natural, year 10 planted) with the projection dashed beyond it,
# and each 90% band carries a thin edge so the three bands can be told apart. Same benchmark (first 42 lines of script 39) and same saved scenarios.
L <- readLines("~/jobs/koa_final_eq_20261110/scripts/39_b2_items.R"); eval(parse(text = L[1:42])); MC <- fread("ms_v136/scenarios_long_j1.csv"); dir.create("ms_v137", showWarnings = FALSE)
OR <- c(Natural = "#0072B2", Planted = "#D55E00"); LV <- c(Low = "#56B4E9", Median = "#009E73", High = "#CC79A7"); INK <- "#1B2A49"; orig <- function(p) factor(ifelse(p == 1, "Planted", "Natural"), levels = names(OR))
theme_koa <- function() theme_classic(base_size = 11) + theme(axis.text = element_text(colour = "black", size = 9), axis.title = element_text(face = "bold", size = 9.5), legend.position = "bottom", legend.title = element_blank(), legend.text = element_text(size = 9), legend.key.size = unit(4, "mm"), plot.tag = element_text(face = "bold", size = 11), strip.background = element_blank(), strip.text = element_text(face = "bold", size = 10), plot.margin = margin(6, 8, 3, 3), panel.spacing.x = unit(8, "mm"))
last[, origin := orig(planted)]; bp <- function(o, p, xl, yl, lim, strip = FALSE, brk = waiver()) { d <- data.table(o = last[[o]], p = last[[p]], origin = last$origin, h = last$h); mx <- if (is.null(lim)) max(c(d$o, d$p)) * 1.05 else lim
  ggplot(d, aes(p, o)) + annotate("ribbon", x = c(0, mx), ymin = c(0, 0.75 * mx), ymax = c(0, 1.25 * mx), fill = "#56B4E9", alpha = 0.25) + geom_abline(slope = 1, intercept = 0, linewidth = 0.3, colour = "#0072B2") + geom_point(aes(fill = h), shape = 21, size = 1.7, stroke = 0.2) + facet_wrap(~origin) +
    scale_fill_viridis_c(option = "plasma", end = 0.9, name = "Horizon (yr)", limits = range(last$h)) + scale_x_continuous(breaks = brk) + scale_y_continuous(breaks = brk) + coord_cartesian(xlim = c(0, mx), ylim = c(0, mx), expand = FALSE) + labs(x = xl, y = yl) + theme_koa() +
    theme(legend.title = element_text(size = 9, face = "bold", vjust = 0.85, margin = margin(r = 8)), legend.key.width = unit(12, "mm"), strip.text = if (strip) element_text(face = "bold", size = 10) else element_blank()) }
fig4 <- (bp("o_surv", "p_surv", "Projected survival (proportion)", "Observed survival\n(proportion)", 1.05, TRUE, seq(0, 1, 0.25)) / bp("o_qmd", "p_qmd", "Projected QMD (cm)", "Observed QMD\n(cm)", NULL) / bp("o_ba", "p_ba", "Projected basal area (m² ha⁻¹)", "Observed basal area\n(m² ha⁻¹)", NULL)) + plot_layout(guides = "collect") + plot_annotation(tag_levels = "a", tag_prefix = "(", tag_suffix = ")") & theme(legend.position = "bottom")
ggsave("ms_v137/Fig4_benchmark.png", fig4, width = 140, height = 185, units = "mm", dpi = 300, type = "cairo")
sc <- MC[site_dev == FALSE & var %in% c("BA", "QMD", "TPH")]; sc[, `:=`(origin = orig(planted), lev = factor(c(lo = "Low", md = "Median", hi = "High")[level], levels = names(LV)))]; vl <- c(BA = "Basal area (m² ha⁻¹)", QMD = "QMD (cm)", TPH = "Stems (ha⁻¹)"); sc[, vlab := factor(vl[var], levels = vl)]
shade <- data.table(origin = orig(c(0, 1)), xmin = c(33, 10)); sc <- merge(sc, shade, by = "origin"); lab <- data.table(origin = orig(c(0, 1)), vlab = factor(vl[["BA"]], levels = vl), x = c(35, 12), label = "Extrapolation")
fig5 <- ggplot(sc, aes(year, point, colour = lev, fill = lev)) + geom_ribbon(aes(ymin = p05, ymax = p95), alpha = 0.13, linewidth = 0.2, linetype = "solid") + geom_vline(data = shade, aes(xintercept = xmin), colour = INK, linewidth = 0.35, linetype = "22") +
  geom_line(data = sc[year <= xmin], linewidth = 0.6) + geom_line(data = sc[year >= xmin], linewidth = 0.6, linetype = "42") + geom_text(data = lab, aes(x, Inf, label = label), inherit.aes = FALSE, hjust = 0, vjust = 1.4, size = 3.2, fontface = "bold", colour = INK) +
  facet_grid(vlab ~ origin, scales = "free_y", switch = "y") + scale_colour_manual(values = LV, labels = paste(names(LV), "BYI")) + scale_fill_manual(values = LV, labels = paste(names(LV), "BYI")) + scale_y_continuous(limits = c(0, NA), expand = expansion(mult = c(0, 0.04))) + labs(x = "Years from starting measurement", y = NULL) + theme_koa() + theme(strip.placement = "outside", strip.text.y.left = element_text(face = "bold", size = 9.5), legend.key.width = unit(8, "mm"))
ggsave("ms_v137/Fig5_projections.png", fig5, width = 140, height = 170, units = "mm", dpi = 300, type = "cairo")
cat("Figs. 4 and 5 written to ms_v137\n")
